<?php get_header(); ?><main id="main" class="archive-main site-shell"><header class="page-hero"><span class="eyebrow"><?php esc_html_e('Index','stillform'); ?></span><h1><?php echo esc_html(is_home()?__('Journal','stillform'):get_the_archive_title()); ?></h1></header><div class="journal-list"><?php if(have_posts()): while(have_posts()): the_post(); ?><article><span><?php echo esc_html(get_the_date('d.m.Y')); ?></span><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><div><?php the_excerpt(); ?></div></article><?php endwhile; the_posts_pagination(); else: ?><p><?php esc_html_e('No entries yet.','stillform'); ?></p><?php endif; ?></div></main><?php get_footer(); ?>